package com.mailservice

import java.text.Normalizer
import java.util.concurrent.{ConcurrentLinkedQueue, Semaphore}
import javax.mail._
import javax.mail.internet._
import java.util.Properties

case class PooledConnection(session: Session, transport: Transport)

class ConnectionPool(maxSize: Int, smtpHost: String, smtpPort: Int) {
  private val pool = new ConcurrentLinkedQueue[PooledConnection]()
  private val semaphore = new Semaphore(maxSize)

  def acquire(): PooledConnection = {
    semaphore.acquire()
    Option(pool.poll()).getOrElse(createConnection())
  }

  def release(conn: PooledConnection): Unit = {
    pool.offer(conn)
    semaphore.release()
  }

  private def createConnection(): PooledConnection = {
    val props = new Properties()
    props.put("mail.smtp.host", smtpHost)
    props.put("mail.smtp.port", smtpPort.toString)
    props.put("mail.smtp.auth", "true")
    // Enforce encrypted transport (STARTTLS) to prevent cleartext transmission
    props.put("mail.smtp.starttls.enable", "true")
    props.put("mail.smtp.starttls.required", "true")
    props.put("mail.smtp.ssl.checkserveridentity", "true")
    val session = Session.getInstance(props)
    val transport = session.getTransport("smtp")
    transport.connect()
    PooledConnection(session, transport)
  }
}

object EmailValidator {
  // Allowed domains for internal routing
  private val allowedDomains = Set("company.com", "internal.corp", "partner.org")

  // Normalize email to canonical form for comparison
  def normalizeEmail(email: String): String = {
    val trimmed = email.trim.toLowerCase
    // NFC normalization for consistent Unicode representation
    Normalizer.normalize(trimmed, Normalizer.Form.NFC)
  }

  // Extract domain from email address
  def extractDomain(email: String): String = {
    val atIndex = email.lastIndexOf('@')
    if (atIndex < 0) throw new IllegalArgumentException("Invalid email")
    email.substring(atIndex + 1)
  }

  // Validate that email belongs to allowed domain
  def isAllowedDomain(email: String): Boolean = {
    val domain = extractDomain(email)
    allowedDomains.contains(domain)
  }

  // Check for header injection characters
  def isSafeForHeaders(input: String): Boolean = {
    !input.contains("\r") && !input.contains("\n") && !input.contains("\u0000")
  }
}

class EmailService(pool: ConnectionPool) {

  def sendEmail(to: String, from: String, subject: String, body: String): Either[String, Unit] = {
    // Step 1: Normalize the email first for all subsequent checks
    val normalizedTo = EmailValidator.normalizeEmail(to)
    val normalizedFrom = EmailValidator.normalizeEmail(from)

    // Step 2: Validate header safety on normalized input
    if (!EmailValidator.isSafeForHeaders(normalizedTo) || 
        !EmailValidator.isSafeForHeaders(normalizedFrom) ||
        !EmailValidator.isSafeForHeaders(subject)) {
      return Left("Invalid characters detected")
    }

    // Step 3: Validate domain on normalized form
    if (!EmailValidator.isAllowedDomain(normalizedTo)) {
      return Left(s"Domain not allowed: ${EmailValidator.extractDomain(normalizedTo)}")
    }

    // Step 4: Send using the NORMALIZED address (canonical form)
    doSend(normalizedTo, normalizedFrom, subject, body)
  }

  private def doSend(to: String, from: String, subject: String, body: String): Either[String, Unit] = {
    var conn: PooledConnection = null
    try {
      conn = pool.acquire()
      val message = new MimeMessage(conn.session)
      message.setFrom(new InternetAddress(from))
      message.setRecipient(Message.RecipientType.TO, new InternetAddress(to))
      message.setSubject(subject)
      message.setText(body, "UTF-8")
      conn.transport.sendMessage(message, message.getAllRecipients)
      Right(())
    } catch {
      case e: Exception => Left(s"Send failed: ${e.getMessage}")
    } finally {
      if (conn != null) pool.release(conn)
    }
  }
}

// Application entry point
object MailApp {
  def main(args: Array[String]): Unit = {
    val pool = new ConnectionPool(5, "smtp.company.com", 587)
    val service = new EmailService(pool)

    // Example usage from web handler
    val result = service.sendEmail(
      to = "user@company.com",
      from = "noreply@company.com",
      subject = "Welcome",
      body = "Hello and welcome!"
    )
    result match {
      case Right(_) => println("Email sent successfully")
      case Left(err) => println(s"Error: $err")
    }
  }
}
